"""Generate legacy interior-window diagnostics without supplying original values."""
from pathlib import Path
import argparse,hashlib,importlib.util,json
R=Path(__file__).resolve().parents[1];sha=lambda b:hashlib.sha256(b).hexdigest()
PATCHES=[("const sceneEvents=phasedScheduler?stageEvents('scene-camera-copy-events.jsonl'):[];\n", "const legacyPerspectiveWindows=[];\nconst sceneEvents=phasedScheduler?stageEvents('scene-camera-copy-events.jsonl'):[];\n"), ("  const map=boundary.event==='world-perspective-right-written'?afterDrawWorker:beforeDrawWorker;\n", "  if(boundary.event==='world-perspective-right-written'){\n   const frame=cameraBoundaryEvents.filter(x=>x.event==='world-perspective-right-written'&&x.precedingPlayerCallbacks===callback);\n   const ordinal=frame.findIndex(x=>x.hostMonotonicNs===boundary.hostMonotonicNs&&x.threadId===boundary.threadId&&x.pc===boundary.pc)+1;\n   assert(ordinal>0);\n   // An interior observed interval has a following perspective event. The last\n   // interval may contain screen compositing; retain its original scheduling.\n   if(ordinal<frame.length){\n    const following=frame[ordinal],after=sceneEvents.find(x=>x.stage===e.stage&&x.event==='scene-camera-copy-after');\n    assert(after&&boundary.hostMonotonicNs<e.hostMonotonicNs&&e.hostMonotonicNs<following.hostMonotonicNs);\n    assert.equal(boundary.pc,0x4465a6);assert.equal(e.pc,0x40d435);\n    assert.equal(c.diagnostic_mode_window(e.stage,callback,ordinal,baseNow+BigInt(e.hostMonotonicNs)-playerOrigin),1);\n    legacyPerspectiveWindows.push({stage:e.stage,callback,ordinal,readyNs:e.hostMonotonicNs,previousNs:boundary.hostMonotonicNs,followingNs:following.hostMonotonicNs,copyAfterNs:after.hostMonotonicNs,copyCompletedBeforeFollowing:after.hostMonotonicNs<following.hostMonotonicNs,fullSourceReadWitnessPresent:false,exactOriginalInstructionScheduleRecovered:false});\n    continue;\n   }\n  }\n  const map=boundary.event==='world-perspective-right-written'?afterDrawWorker:beforeDrawWorker;\n"), ("write(resolve(out,'full-camera-report.json'),JSON.stringify({readOnlyExpandedCameraObservation:true,firstCallback:2,callbacksCompared:rows.length/32-1,nativeWordIndices:fullCameraIndices,comparedFieldsPerCallback:71,opaqueNativeWordIndicesNotAccepted:[22,23],nativeTrailingWordsNotCaptured:[73,74],counts:fullCameraCounts,first:fullCameraFirst,allExpandedCapturedWordsEqual:Object.keys(fullCameraCounts).length===0,portableSha256:sha(fullBytes),hostClockOverridesAdded:false,originalStateValuesProvidedToEngine:false,completeGame:false},null,2)+'\\n',{flag:'wx'});\n", "write(resolve(out,'full-camera-report.json'),JSON.stringify({readOnlyExpandedCameraObservation:true,firstCallback:2,callbacksCompared:rows.length/32-1,nativeWordIndices:fullCameraIndices,comparedFieldsPerCallback:71,opaqueNativeWordIndicesNotAccepted:[22,23],nativeTrailingWordsNotCaptured:[73,74],counts:fullCameraCounts,first:fullCameraFirst,allExpandedCapturedWordsEqual:Object.keys(fullCameraCounts).length===0,portableSha256:sha(fullBytes),hostClockOverridesAdded:true,originalStateValuesProvidedToEngine:false,completeGame:false},null,2)+'\\n',{flag:'wx'});\n"), ("write(resolve(out,'report.json'),JSON.stringify(report,null,2)+'\\n',{flag:'wx'});console.log(JSON.stringify(report));\n", "report.legacyPerspectiveWindows=legacyPerspectiveWindows;report.addedMeasuredHostClockBoundary=true;report.legacyWindowDiagnosticOnly=true;report.strictSceneContractAccepted=false;report.exactOriginalInstructionScheduleRecovered=false;report.ordinaryIndependentThreadTimingAcceptance=false;\nreport.legacyWindowStates=legacyPerspectiveWindows.map(w=>({stage:w.stage,delivered:c.diagnostic_mode_window_state(w.stage,0),failed:c.diagnostic_mode_window_state(w.stage,1),visits:c.diagnostic_mode_window_state(w.stage,2)}));\nassert(report.legacyWindowStates.every(w=>w.delivered===1&&!w.failed));\n\nwrite(resolve(out,'report.json'),JSON.stringify(report,null,2)+'\\n',{flag:'wx'});console.log(JSON.stringify(report));\n")]
def driver_source():
 p=R/'tools/th14-prepare-full-camera-drivers-nov04.py';spec=importlib.util.spec_from_file_location('base',p);g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
 text=g.driver_source().decode().replace('\r\n','\n')
 for old,new in PATCHES:
  assert text.count(old)==1; text=text.replace(old,new)
 return text.replace('\n','\r\n').encode()

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true',required=True);p.parse_args()
 path=R/'tools/th14-compare-native-mode-perspective-window-nov04.mjs';data=driver_source();assert data==path.read_bytes()
